import json
from pathlib import Path

from mock_api import TRACE, fetch_weather
from request_audit import build_failure_entry, summarize_batch
from validation_contract import WEATHER_RULES


def validate_request(request):
    errors = []

    city = request.get("city")
    if city is None:
        errors.append({"param": "city", "error": "required", "value": city, "expected": WEATHER_RULES["city"]})
    elif not isinstance(city, str):
        errors.append({"param": "city", "error": "type", "value": city, "expected": WEATHER_RULES["city"]})
    elif not city.strip():
        errors.append({"param": "city", "error": "required", "value": city, "expected": WEATHER_RULES["city"]})

    days = request.get("days")
    if not isinstance(days, int):
        errors.append({"param": "days", "error": "type", "value": days, "expected": WEATHER_RULES["days"]})
    elif days < 1 or days > 14:
        errors.append({"param": "days", "error": "range", "value": days, "expected": WEATHER_RULES["days"]})

    units = request.get("units")
    if units not in {"metric", "imperial"}:
        errors.append({"param": "units", "error": "enum", "value": units, "expected": WEATHER_RULES["units"]})

    return errors


def process_requests(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    successes = []
    failures = []
    for index, request in enumerate(payload):
        errors = validate_request(request)
        if errors:
            failures.append(build_failure_entry(index, request, errors))
            continue
        successes.append(fetch_weather(**request))
    return summarize_batch(successes, failures, TRACE)

